from autore import Modulo,estratto
from tikz_base import scrivi,n,a,rect,linea
m=Modulo('M09','Serie temporali ambientali','Calendario, dipendenza, trasformazioni e stazionarietà')
def p(t,s,**kw):m.pagina(t,s,**kw)
def d(i,b):return scrivi('M09',i,b)
m.sezione_nuova('Tempo e provenienza delle osservazioni')
p('L’ordine temporale appartiene all’informazione',
'''Una serie associa ogni osservazione a un istante o a un intervallo, del quale occorre conoscere durata e significato. Rimescolando le righe si conservano media e distribuzione dei valori, mentre vengono distrutte successione e dipendenza. Descrivere il passato, riconoscere un cambiamento e prevedere il futuro richiedono pertanto procedure differenti. Una sequenza lungo una carota o una traversa di microsonda presenta un ordine spaziale, che può essere trattato analogamente soltanto dichiarando coordinate, spaziatura e natura del processo.''',formula=r'\{(t_i,x_i)\}_{i=1}^n,\qquad t_1<\cdots<t_n',tikz=d('D01',a(.5,2.1,7,2.1)+''.join(n(x,1.3,rf'$t_{{{i}}}$')+n(x,3,rf'$x_{{{i}}}$')+linea(x,1.9,x,2.3,'Classical') for i,x in enumerate([1,2.7,4.4,6.1],1))+a(1,3.8,2.7,3.8)+a(2.7,3.8,4.4,3.8)+a(4.4,3.8,6.1,3.8)+n(3.7,5.3,'Le distanze fra tempi hanno un significato.',w=6.7,size=11)),richiamo='Il calendario e l’unità dell’asse ordinato fanno parte della definizione del dato.',origine='M09:1–10,13–15')
p('La CO₂ del laboratorio è un archivio storico',
'''La serie allegata deriva dalla copia distribuita con statsmodels delle medie settimanali storiche attribuite a Keeling e Whorf e al CDIAC. Il file contiene 2.284 date, delle quali 59 hanno valore mancante. La versione mensile è stata costruita mediando i valori settimanali disponibili in ciascun mese; la sua definizione differisce da quella di una media mensile ufficiale. L’archivio consente di studiare tendenza, oscillazione stagionale e copertura, mantenendo espliciti periodo e provenienza.''',figura='M09/F01',didascalia='Medie mensili derivate dall’archivio settimanale storico; i dati rappresentano il periodo 1958–2001.',richiamo='Una trasformazione locale di dati pubblicati deve conservare la propria definizione e la fonte originaria.',origine='M09:4,10–12,29')
p('Un calendario completo rende visibili le assenze',
'''Prima di costruire una serie regolare si convertono le date, si ordinano le righe e si confrontano gli istanti osservati con la griglia attesa. Se manca il giorno tre, eliminare la sua posizione renderebbe artificialmente adiacenti i giorni due e quattro. Le date duplicate richiedono invece di stabilire se si tratti di repliche, sensori diversi o errori di registrazione. Un cambiamento di sito, strumento o protocollo deve accompagnare la serie come metadato, poiché può produrre discontinuità apparentemente ambientali.''',tikz=d('D02',n(3.7,.4,'Griglia giornaliera attesa')+''.join(rect(.3+i*1.4,1.4,1.5+i*1.4,3.2,'Quantum' if i==2 else 'Classical',15 if i==2 else 5)+n(.9+i*1.4,1.9,str(i+1))+n(.9+i*1.4,2.7,'NA' if i==2 else r'$x$',size=11) for i in range(5))+n(3.7,4.5,'L’assenza conserva la propria posizione.',w=6.8)+n(3.7,5.5,'Rimuovere la riga comprimerebbe il tempo.',w=6.8,size=11)),richiamo='La regolarità temporale va verificata prima di assegnare una frequenza alla serie.',origine='M09:16–25')
c=estratto('M09','calendario',"d <- read.csv('dati/co2_1985_2001.csv')\nd$data <- as.Date(d$data)\nd <- d[order(d$data),]\ngriglia <- seq(min(d$data),max(d$data),by='month')\nstopifnot(identical(d$data,griglia))\nstopifnot(!anyNA(d$co2_ppm))\ny <- ts(d$co2_ppm,start=c(1985,1),frequency=12)\nstart(y); end(y); frequency(y)")
p('Un oggetto ts presuppone una griglia regolare',
'''La classe ts codifica inizio e frequenza di una successione equispaziata, senza conservare date civili per ogni elemento. Il codice verifica quindi la griglia mensile e la completezza del segmento 1985–2001 prima di attribuirgli frequenza dodici. La tabella con le date resta necessaria per ricondurre risultati e grafici al calendario. Un valore NA mantiene la posizione di un’assenza, mentre la sua gestione dipende dalla procedura applicata successivamente.''',codice=c,richiamo='La frequenza di ts descrive il numero di passi per ciclo, non dimostra che il file sia regolare.',origine='M09:17–25')

m.sezione_nuova('Aggregazione, copertura e risoluzione')
p('La copertura condiziona il significato di una media',
'''Una media mensile basata su poche osservazioni settimanali può rappresentare soltanto una porzione del mese, soprattutto quando le assenze sono concentrate. Il conteggio delle osservazioni disponibili accompagna quindi ogni aggregato. Nel segmento 1985–2001 utilizzato per la previsione, tutti i mesi hanno almeno tre valori settimanali; nell’archivio completo la copertura è più eterogenea. Somme, medie, massimi e quantili rispondono a domande differenti e richiedono regole esplicite per i periodi incompleti.''',figura='M09/F02',didascalia='Numero di mesi per conteggio dei valori settimanali disponibili nell’archivio mensile derivato.',formula=r'\bar x_m=\frac{1}{n_m}\sum_{i\in m,\ x_i\ \mathrm{osservato}}x_i',richiamo='Il valore aggregato deve essere accompagnato dalla copertura che lo sostiene.',origine='M09:21,26–27,29,33–35')
p('La media delle medie richiede pesi coerenti',
'''Se più periodi contengono numerosità diverse, la media aritmetica delle loro medie assegna uguale peso ai periodi, mentre la media di tutte le osservazioni assegna uguale peso alle singole misure. Le due quantità coincidono con numerosità uguali. Per intervalli di durata diversa possono essere appropriati pesi temporali. Nel file CO₂ la media mensile usa medie settimanali assegnate al mese della data, secondo una convenzione locale documentata.''',formula=r'\bar x_{\rm osservazioni}=\frac{\sum_m n_m\bar x_m}{\sum_m n_m}\\ \bar x_{\rm periodi}=\frac1M\sum_m\bar x_m',destra='Esempio: due periodi hanno medie 10 e 20, calcolate rispettivamente su 2 e 8 misure. La media delle osservazioni vale 18, mentre la media equi ponderata dei periodi vale 15.'.replace('equi ponderata','equiponderata'),richiamo='Pesi per osservazione, periodo e durata definiscono quantità differenti.',origine='M09:28–29,34–35')
p('Risoluzione temporale e aliasing',
'''Aggregare su intervalli più ampi attenua variazioni rapide e picchi, modificando la domanda cui la serie può rispondere. Un campionamento troppo rado può inoltre rendere indistinguibili oscillazioni diverse: è il fenomeno dell’aliasing. Nel caso ideale di un segnale limitato in frequenza, la frequenza di campionamento deve superare il doppio della massima frequenza da ricostruire. Assenze, irregolarità e rumore richiedono ulteriori verifiche nei dati ambientali.''',formula=r'f_s>2f_{\max}\quad\text{nel modello ideale senza aliasing}',tikz=d('D03',linea(.5,3.1,7,3.1)+r'\draw[Classical,domain=.6:6.8,samples=120,line width=1pt] plot (\x,{3.1-1.1*cos(180*(\x-.6))});\draw[Quantum,dashed,line width=1pt] (.6,2)--(6.6,2);'+''.join(rf'\fill[Ink] ({x},2) circle (2.4pt);' for x in [.6,2.6,4.6,6.6])+n(3.7,.7,'Campioni sempre nella stessa fase',w=6.6)+n(3.7,5.2,'Oscillazione e costante coincidono ai campioni.',w=6.8,size=11)),richiamo='L’assenza di oscillazioni nei dati può dipendere dalla risoluzione del campionamento.',origine='M09:30–33')

m.sezione_nuova('Componenti, smoothing e riferimenti')
p('Trend e stagione descrivono scale differenti',
'''Una rappresentazione additiva separa un andamento graduale, una componente periodica e un resto. Nella temperatura sintetica il generatore rende note le prime due componenti, consentendo di confrontarle con la serie osservata. La stagionalità segue una periodicità di calendario, mentre oscillazioni con durata variabile richiedono una descrizione diversa. La separazione dipende dal modello e dalla scala temporale: un cambiamento brusco può riflettere una trasformazione ambientale oppure una discontinuità del protocollo di misura.''',formula=r'X_t=T_t+S_t+R_t,\qquad S_{t+12}=S_t',figura='M09/F04',didascalia='Primi cinque anni della temperatura simulata. Trend: 12 + 0,012t, con t = 0 nel gennaio 2000; stagione di ampiezza 8 °C.',richiamo='Il resto può conservare dipendenza, cambi di varianza o altre strutture non rappresentate.',origine='M09:36–45')
p('La finestra determina quali variazioni restano visibili',
'''Una media mobile sostituisce ogni osservazione con una combinazione di valori vicini. Allargando la finestra si attenuano oscillazioni più lente, oltre al rumore di breve periodo, e si perde dettaglio sui cambiamenti locali. La figura confronta finestre centrate di tre e tredici mesi, mantenendo visibili i dati originari. Ai bordi manca una parte dei vicini: lo script conserva valori mancanti per le finestre incomplete, evitando di attribuire loro la stessa definizione delle finestre interne.''',formula=r'M_t^{(q)}=\frac1{2q+1}\sum_{j=-q}^{q}X_{t+j}',figura='M09/F03',didascalia='Temperatura osservata in grigio; medie mobili centrate a 3 e 13 mesi. Gli estremi privi di finestra completa restano assenti.',richiamo='La larghezza e la regola ai bordi fanno parte della definizione dello smoothing.',origine='M09:46–49,52,54–55')
p('Una finestra centrata utilizza osservazioni future',
'''La media centrata descrive retrospettivamente una serie, poiché per il valore al tempo t utilizza anche osservazioni successive. Una media retrospettiva impiega invece soltanto il presente e il passato, introducendo un diverso ritardo rispetto ai cambiamenti. Se una trasformazione centrata viene calcolata sull’intero archivio prima della valutazione predittiva, può trasferire informazione futura nei dati di addestramento. Il diagramma rende esplicita la disponibilità temporale dei valori inclusi nella finestra.''',formula=r'M_t^{\rm passato}=\frac1q\sum_{j=0}^{q-1}X_{t-j}',tikz=d('D04',n(3.7,.4,'Finestra di cinque osservazioni')+''.join(n(.8+i*1.4,1.3,x,size=11) for i,x in enumerate(['t − 2','t − 1','t','t + 1','t + 2']))+rect(.3,1.9,7.1,2.8,'Quantum',15)+n(3.7,2.35,'Centrata: comprende il futuro',w=6.4,size=11)+r'\draw[Measure,dashed] (4.2,.9)--(4.2,5.2);'+rect(.3,3.6,4,4.5)+n(2.15,4.05,'Valori disponibili a t',w=3.4,size=10.8)+n(3.7,5.7,'La linea separa presente e futuro.',w=6.8,size=11)),richiamo='Una trasformazione usata per prevedere deve rispettare l’informazione disponibile all’origine.',origine='M09:48,54–55,103')
p('Mediana mobile e regressioni locali',
'''La mediana mobile attenua l’influenza di picchi isolati, pur potendo eliminare eventi che hanno un significato fisico. LOESS adatta invece regressioni locali con pesi che diminuiscono con la distanza temporale; la frazione di dati utilizzata controlla la flessibilità della curva. La scelta va valutata sul grafico dei valori originari, considerando bordi e assenze. Il termine media mobile usato nello smoothing identifica una trasformazione dei dati, mentre un modello MA descrive una combinazione di innovazioni casuali.''',formula=r'\widehat m(t)=\widehat\beta_0(t)\quad\text{da regressione locale pesata}',destra='Per una finestra pari, una media centrata richiede una convenzione ulteriore sul posizionamento. Un filtro stagionale classico 2×12 applica una seconda media per riallineare il centro ai mesi; la figura precedente usa tredici mesi per conservare una finestra dispari esplicita.',richiamo='Finestra, robustezza e collocazione temporale determinano il significato della curva smussata.',origine='M09:49–55')
p('Un’anomalia è riferita a una base dichiarata',
'''Sottrarre una media mensile di riferimento produce un’anomalia nelle stesse unità della variabile. Nel caso sintetico la base viene stimata sui primi cinque anni e poi mantenuta fissa, così che l’evoluzione successiva rimanga visibile rispetto a quel periodo. Se si dividesse anche per una deviazione standard mensile, si otterrebbe uno scarto standardizzato privo di unità. Un riferimento stimato sull’intero archivio serve a descrivere quell’archivio, ma incorporerebbe informazioni future se usato per valutarne una previsione passata.''',formula=r'A_t=X_t-\bar X_{m(t),\,B}',figura='M09/F05',didascalia='Anomalie della temperatura rispetto alle medie dei mesi nel periodo 2000–2004, mantenute fisse per tutti gli anni.',richiamo='Periodo di riferimento, copertura e unità devono accompagnare ogni serie di anomalie.',origine='M09:56–65')
c=estratto('M09','anomalie',"d <- read.csv('dati/temperatura_simulata.csv')\nd$data <- as.Date(d$data)\nd$mese <- as.integer(format(d$data,'%m'))\nb <- subset(d,data<as.Date('2005-01-01'))\nr <- aggregate(temperatura_C~mese,b,mean)\nd$base <- r$temperatura_C[match(d$mese,r$mese)]\nd$anomalia <- d$temperatura_C-d$base\nhead(d[c('data','temperatura_C','base','anomalia')])")
p('Conservare osservazione, riferimento e anomalia',
'''La tabella mantiene osservazione, base e anomalia per ogni data, rendendo reversibile la trasformazione. Uno scostamento elevato può dipendere da un evento ambientale, da un errore di misura o dall’inadeguatezza del riferimento: la sua interpretazione richiede quindi informazioni ulteriori rispetto al residuo numerico. Quando il sistema evolve, una base fissa mostra il cambiamento rispetto al passato, mentre una base mobile misura lo scarto da condizioni che vengono progressivamente aggiornate.''',codice=c,richiamo='La soglia di interesse fisico deve essere motivata separatamente dalla definizione dell’anomalia.',origine='M09:59–65')

m.sezione_nuova('Ritardi e autocorrelazione')
p('Coppie di osservazioni e ritardo temporale',
'''Il ritardo k separa due osservazioni di k passi della griglia. Per una serie mensile, il primo ritardo confronta mesi consecutivi e il dodicesimo lo stesso mese in anni successivi. Il diagramma al ritardo uno mostra coppie successive dell’AR(1) sintetico, rendendo visibile la persistenza. Se la serie contiene trend o stagionalità, l’associazione fra valori ritardati può riflettere tali componenti; l’ACF dei livelli deve quindi essere letta insieme al grafico temporale e alle trasformazioni adottate.''',formula=r'(X_{t-k},X_t),\qquad t=k+1,\ldots,n',figura='M09/F06',didascalia='Coppie consecutive del processo AR(1) simulato. La retta riassume l’associazione al ritardo uno.',richiamo='Il significato fisico di un lag dipende dalla frequenza e dalla regolarità della griglia.',origine='M09:66–68,74–75')
p('Autocovarianza e autocorrelazione',
'''Per un processo debolmente stazionario, l’autocovarianza dipende dalla distanza temporale e non dal tempo assoluto. Dividendo per la varianza si ottiene l’autocorrelazione. La stima campionaria usata da acf centra l’intera serie e mantiene al denominatore la somma quadratica completa; per questo differisce leggermente dalla correlazione calcolata separatamente sulle due porzioni ritardate. La formula esplicita la convenzione e le coppie utilizzate.''',formula=r'\rho(k)=\frac{\gamma(k)}{\gamma(0)},\quad\gamma(k)=\operatorname{Cov}(X_t,X_{t-k})\\ \widehat\rho(k)=\frac{\sum_{t=k+1}^n(x_t-\bar x)(x_{t-k}-\bar x)}{\sum_{t=1}^n(x_t-\bar x)^2}',destra='La PACF al ritardo k misura l’associazione lineare residua fra estremi dopo l’aggiustamento per i ritardi intermedi. Per un AR(p) ideale la PACF si annulla oltre p, proprietà utile come indizio insieme alle altre diagnosi.',richiamo='ACF e PACF stimano relazioni differenti e richiedono una serie e una convenzione esplicite.',origine='M09:68,73–75')
p('Lettura delle bande dell’ACF',
'''Sotto un’ipotesi di rumore bianco e con numerosità sufficiente, le autocorrelazioni campionarie a ritardi positivi hanno approssimativamente errore standard pari all’inverso della radice di n. Le bande usuali forniscono quindi un confronto puntuale, senza correggere la lettura simultanea di molti ritardi. Nella figura la persistenza dell’AR(1) viene confrontata con la curva teorica. Le bande rappresentano il riferimento di assenza di autocorrelazione, la cui interpretazione differisce da un intervallo per la curva.''',formula=r'\widehat\rho(k)\approx N(0,\,1/n)',figura='M09/F07',didascalia='Segmenti: ACF campionaria; curva: 0,65 elevato al ritardo. Bande tratteggiate: ±1,96/√n, riferimento puntuale sotto rumore bianco.',richiamo='Ispezionare molti ritardi aumenta la possibilità di superamenti occasionali delle bande.',origine='M09:69–75')

m.sezione_nuova('Processi e stazionarietà')
p('Le condizioni di stazionarietà debole',
'''Un processo è debolmente stazionario quando ha media costante, varianza finita costante e covarianza dipendente soltanto dal ritardo. Una traiettoria con media apparentemente stabile può violare la condizione sulla varianza, mentre una stagionalità nella media viola la costanza temporale anche se si ripete regolarmente. Le proprietà riguardano il processo che genera possibili traiettorie; un singolo grafico fornisce evidenza parziale, sulla quale si costruisce una diagnosi coerente con il contesto e il modello.''',formula=r'E[X_t]=\mu,\quad\operatorname{Var}(X_t)=\sigma^2<\infty\\ \operatorname{Cov}(X_t,X_{t-k})=\gamma(k)',tikz=d('D05',n(3.7,.4,'Traslare due tempi dello stesso intervallo')+a(.5,2,7,2)+n(1.2,1.4,r'$t$')+n(3,1.4,r'$t+k$')+n(4.4,2.8,r'$t+h$')+n(6.2,2.8,r'$t+h+k$')+linea(1.2,1.8,1.2,2.2)+linea(3,1.8,3,2.2)+linea(4.4,1.8,4.4,2.2,'Quantum')+linea(6.2,1.8,6.2,2.2,'Quantum')+n(3.7,4.3,r'La covarianza resta $\gamma(k)$.',w=6.8)+n(3.7,5.5,'Contano gli scarti temporali, non l’origine.',w=6.8,size=11)),richiamo='Una media costante costituisce soltanto una delle condizioni di stazionarietà debole.',origine='M09:76–79,83')
p('Il rumore bianco esclude autocovarianze non nulle',
'''Un rumore bianco ha media nulla, varianza costante e autocovarianza nulla fra tempi distinti. L’indipendenza costituisce una proprietà ulteriore, che vale nel caso di innovazioni gaussiane indipendenti usato nelle simulazioni. La distinzione è rilevante perché una serie può essere incorrelata pur conservando dipendenze in funzioni dei valori, come i quadrati. Dopo la stima di un modello, residui compatibili con rumore bianco indicano che la struttura lineare considerata è stata adeguatamente rappresentata, entro i limiti della diagnosi.''',formula=r'E[\varepsilon_t]=0,\quad\operatorname{Var}(\varepsilon_t)=\sigma^2\\ \operatorname{Cov}(\varepsilon_t,\varepsilon_s)=0\quad(t\ne s)',destra='Esercizio: rimescolare una realizzazione AR(1) conserva l’istogramma ma altera l’ACF. Il confronto distingue la distribuzione marginale, che descrive i singoli valori, dalla struttura temporale, che descrive il loro ordinamento congiunto.',richiamo='L’assenza di correlazione lineare non esclude ogni forma di dipendenza temporale.',origine='M09:8,14–15,69,79')
p('Nell’AR(1) stazionario gli shock si attenuano',
'''Nel modello autoregressivo di ordine uno, il valore corrente combina una frazione del precedente con una nuova innovazione. Quando il modulo del coefficiente è minore di uno, la soluzione stazionaria può essere espressa come una somma di innovazioni passate con pesi geometrici. L’influenza di uno shock diminuisce quindi nel tempo. La serie allegata usa coefficiente 0,65 e inizia da zero: l’inizializzazione introduce un breve transitorio rispetto alla distribuzione stazionaria teorica.''',formula=r'X_t=\phi X_{t-1}+\varepsilon_t,\quad|\phi|<1\\ X_t=\sum_{j=0}^{\infty}\phi^j\varepsilon_{t-j},\quad\rho(k)=\phi^{|k|}',tikz=d('D06',n(3.7,.4,'Risposta a un’innovazione unitaria')+linea(.5,4.9,7,4.9)+''.join(rect(.7+i*1.2,4.9-3.5*.65**i,1.4+i*1.2,4.9,'Classical',20)+n(1.05+i*1.2,5.5,str(i),size=11) for i in range(5))+n(3.7,6,'Passi successivi allo shock',w=6.5,size=11)),richiamo='La persistenza è determinata dal coefficiente e dalla struttura delle innovazioni.',origine='M09:70,80,84–85')
p('La varianza dell’AR(1) deriva dall’equilibrio',
'''Nella soluzione stazionaria, l’innovazione corrente è incorrelata con il passato e la varianza è uguale a quella del passo precedente. Applicando la varianza all’equazione del modello si ottiene quindi un’identità che può essere risolta rispetto alla varianza del processo. Quando il coefficiente si avvicina a uno, aumenta sia la dispersione sia la durata della memoria. La dipendenza riduce la precisione della media rispetto a osservazioni indipendenti di uguale varianza.''',formula=r'\gamma(0)=\phi^2\gamma(0)+\sigma_\varepsilon^2\\ \gamma(0)=\frac{\sigma_\varepsilon^2}{1-\phi^2}',destra=r'Per n grande e $0<\phi<1$, la varianza della media è approssimativamente $\gamma(0)(1+\phi)/[n(1-\phi)]$. L’approssimazione richiede memoria sufficientemente breve rispetto alla lunghezza della serie; vicino alla radice unitaria può essere inadeguata.',richiamo='Una forte persistenza diminuisce l’informazione aggiunta da osservazioni temporalmente vicine.',origine='M09:8,70,80,84–85')
p('Nel random walk gli shock si accumulano',
'''Con coefficiente autoregressivo uguale a uno, ogni innovazione si aggiunge permanentemente al livello precedente. Se il valore iniziale è fisso e gli incrementi sono indipendenti con varianza costante, la varianza del livello cresce linearmente con il tempo. Il processo viola quindi la stazionarietà debole anche quando le innovazioni abbiano media nulla. La figura confronta il ritorno dell’AR(1) verso l’equilibrio con l’accumulazione del random walk.''',formula=r'X_t=X_0+\sum_{j=1}^{t}\varepsilon_j,\qquad\operatorname{Var}(X_t)=t\sigma_\varepsilon^2',figura='M09/F08',didascalia='Realizzazioni sintetiche. Le scale verticali sono distinte e dichiarate dagli assi; il confronto riguarda la struttura temporale.',richiamo='La differenza di un random walk restituisce le innovazioni che ne hanno generato gli incrementi.',origine='M09:71,81,84–85')

m.sezione_nuova('Trend, differenze e trasformazioni')
p('Trend deterministico e accumulazione degli shock',
'''Una serie può oscillare intorno a una funzione deterministica del tempo oppure evolvere attraverso shock che si accumulano nel livello. Sottrarre una retta stimata cerca di isolare un processo attorno a un andamento prefissato; differenziare descrive invece incrementi consecutivi. Le due operazioni possono produrre strutture residue differenti anche sulla stessa traiettoria. La scelta deve quindi riflettere un modello del cambiamento, che venga valutato attraverso grafici, dipendenza residua e stabilità delle conclusioni.''',formula=r'X_t=a+bt+U_t\quad\text{oppure}\quad X_t=X_{t-1}+\varepsilon_t',tikz=d('D07',rect(.4,.7,7,2.2)+n(3.7,1.45,r'$X_t=a+bt+U_t$',w=6.2)+a(2,2.4,2,3.3)+a(5.5,2.4,5.5,3.3,'Quantum')+n(1.9,4,r'$X_t-\widehat a-\widehat b t$',w=3.3,size=11)+n(5.5,4,r'$\Delta X_t$',w=3)+n(1.9,5.2,'Scarto dal trend stimato',w=3.3,size=11)+n(5.5,5.2,'Incremento fra tempi',w=3.3,size=11)),richiamo='Detrending e differenziazione rispondono a rappresentazioni differenti del processo.',origine='M09:82,97,100,104–105')
p('La differenza ordinaria e quella stagionale',
'''La differenza ordinaria confronta valori consecutivi, mentre quella stagionale confronta lo stesso periodo in cicli successivi. Per una serie mensile, sottrarre il valore di dodici mesi prima attenua una componente annuale stabile, mantenendo una misura del cambiamento interannuale. Nella CO₂ storica la prima differenza conserva oscillazioni stagionali riconoscibili. Applicare entrambe le differenze produce una trasformazione ulteriore, la cui utilità deve essere verificata evitando di rimuovere struttura già adeguatamente rappresentata.''',formula=r'\Delta X_t=X_t-X_{t-1},\qquad\Delta_{12}X_t=X_t-X_{t-12}',figura='M09/F09',didascalia='Differenze ordinarie e stagionali della CO₂ nel periodo 1985–2001. Ogni valore è associato al tempo finale del confronto.',richiamo='Le differenze mantengono l’unità della variabile, ma descrivono variazioni su intervalli diversi.',origine='M09:97–99,104–105')
p('L’operatore ritardo e la differenza combinata',
'''Definendo B come operatore che sposta indietro di un passo, la differenza ordinaria si scrive uno meno B e quella stagionale uno meno B alla dodicesima. Il prodotto chiarisce quali quattro osservazioni entrino nella differenza combinata e mostra che l’ordine delle due operazioni è intercambiabile, purché la griglia e le assenze siano trattate coerentemente. Le prime tredici posizioni vengono perse perché manca una parte dei valori necessari al confronto.''',formula=r'(1-B)(1-B^{12})X_t\\ =X_t-X_{t-1}-X_{t-12}+X_{t-13}',tikz=d('D08',n(3.7,.5,'Quattro contributi alla differenza combinata')+''.join(rect(.4+j*3.4,1.4+i*1.8,3.2+j*3.4,2.8+i*1.8,'Classical' if i==j else 'Quantum',12)+n(1.8+j*3.4,2.1+i*1.8,txt) for i,row in enumerate([[r'$+X_t$',r'$-X_{t-1}$'],[r'$-X_{t-12}$',r'$+X_{t-13}$']]) for j,txt in enumerate(row))+n(3.7,5.7,'Prima differenza e differenza stagionale commutano.',w=6.8,size=10.8)),richiamo='La lunghezza e l’allineamento temporale del risultato devono essere verificati dopo ogni trasformazione.',origine='M09:97–105')
p('Differenziare troppo può introdurre dipendenza',
'''Se una serie è già rumore bianco, la sua prima differenza contiene due innovazioni consecutive con segni opposti. Due differenze adiacenti condividono quindi un’innovazione con contributi di segno contrario, producendo autocorrelazione negativa al primo ritardo. La figura riproduce questo risultato con una simulazione indipendente. Una forte correlazione negativa dopo la trasformazione può suggerire un eccesso di differenziazione, sebbene la diagnosi richieda il confronto con modelli e altre caratteristiche della serie.''',formula=r'Y_t=\varepsilon_t-\varepsilon_{t-1},\quad\operatorname{Var}(Y_t)=2\sigma^2\\ \operatorname{Cov}(Y_t,Y_{t-1})=-\sigma^2,\quad\rho_Y(1)=-\tfrac12',figura='M09/F10',didascalia='ACF della differenza di 3.000 innovazioni gaussiane indipendenti. Il punto ocra indica il valore teorico −0,5 al primo ritardo.',richiamo='Una trasformazione aggiunge ipotesi e può creare una struttura che prima era assente.',origine='M09:101,104–105')
c=estratto('M09','differenze',"d <- read.csv('dati/co2_1985_2001.csv')\ny <- ts(d$co2_ppm,start=c(1985,1),frequency=12)\nd1 <- diff(y)\nd12 <- diff(y,lag=12)\ndoppia <- diff(d12)\nstopifnot(length(doppia)==length(y)-13)\nstopifnot(isTRUE(all.equal(\n  as.numeric(doppia),as.numeric(diff(d1,lag=12)))))\nstart(doppia); end(doppia)")
p('Le trasformazioni devono conservare un registro',
'''Ogni serie derivata dovrebbe essere accompagnata da formula, parametri, intervallo temporale e regola per le assenze. Il codice verifica la lunghezza della differenza combinata e la concordanza fra due ordini di applicazione, mentre gli attributi temporali permettono di identificarne il primo valore. Per la ricostruzione dei livelli occorrono condizioni iniziali adeguate: una prima differenza conserva gli incrementi e richiede un valore iniziale, mentre differenze stagionali necessitano dei corrispondenti livelli precedenti.''',codice=c,richiamo='Un risultato numericamente corretto può essere interpretato male se viene associato alla data sbagliata.',origine='M09:33,63,97–105')

m.sezione_nuova('Diagnosi con ADF e KPSS')
p('ADF verifica una radice unitaria nel modello scelto',
'''Il test aumentato di Dickey–Fuller esamina la presenza di una radice unitaria in una regressione che può includere costante, trend e differenze ritardate. Sotto l’ipotesi nulla il coefficiente del livello ritardato nella regressione delle differenze è zero. La distribuzione della statistica richiede valori critici specifici, differenti da quelli del test t ordinario. La funzione adf.test di tseries include costante e trend lineare; il numero di ritardi va dichiarato e valutato rispetto alla dipendenza residua e alla numerosità.''',formula=r'\Delta X_t=\alpha+\beta t+\delta X_{t-1}+\sum_{j=1}^k\psi_j\Delta X_{t-j}+u_t\\ H_0:\delta=0',destra='L’alternativa stazionaria è riferita alla specificazione deterministica adottata. Con trend incluso, una serie che oscilla attorno a una retta può essere compatibile con l’alternativa, pur avendo media non costante nei livelli.',richiamo='Il risultato del test deve essere accompagnato da termini deterministici e numero di ritardi.',fonti='tseries: adf.test',origine='M09:86–87,89,92–93')
p('KPSS parte da un’ipotesi di stazionarietà',
'''KPSS assume come ipotesi nulla la stazionarietà attorno a un livello oppure a un trend, secondo la specificazione. La statistica accumula i residui della componente deterministica e li confronta con una stima della varianza di lungo periodo. Risultati ADF e KPSS possono essere concordanti, entrambi poco informativi oppure discordanti, soprattutto con campioni brevi, cambiamenti strutturali o specificazioni inappropriate. Il mancato rifiuto di entrambe le ipotesi può riflettere una limitata capacità di discriminazione.''',formula=r'\eta=\frac{\sum_{t=1}^n S_t^2}{n^2\widehat\omega^2},\qquad S_t=\sum_{j=1}^t e_j',tikz=d('D09',rect(.4,.7,3.3,2.7)+n(1.85,1.7,'ADF: radice unitaria sotto $H_0$',w=2.5,size=11)+rect(4.1,.7,7,2.7,'Quantum')+n(5.55,1.7,'KPSS: stazionarietà sotto $H_0$',w=2.5,size=11)+a(1.85,2.9,2.8,4)+a(5.55,2.9,4.6,4,'Quantum')+n(3.7,4.7,'Confrontare ipotesi e specificazioni',w=6.4)+n(3.7,5.8,'Due mancati rifiuti possono indicare scarsa potenza.',w=6.8,size=10.6)),richiamo='Le due ipotesi nulle sono diverse; la combinazione dei risultati richiede interpretazione.',fonti='tseries: kpss.test',origine='M09:88–95')
c=estratto('M09','test',"p <- read.csv('dati/processi_simulati.csv')\nstopifnot(requireNamespace('tseries',quietly=TRUE))\nx <- p$ar1\ntseries::adf.test(x,k=4)\ntseries::kpss.test(x,null='Level')\ntseries::kpss.test(x,null='Trend')\n# Conservare anche gli avvisi sui limiti\n# delle probabilità tabulate.")
p('Gli avvisi numerici fanno parte del risultato',
'''Le probabilità riportate dalle funzioni possono essere limitate dall’intervallo delle tavole utilizzate. Un avviso che segnala una probabilità inferiore al minimo tabulato deve essere conservato e interpretato come limite, anziché come valore esatto. Nel laboratorio si confrontano rumore bianco, AR(1) e random walk, registrando statistiche, specificazioni e probabilità riportate. Il grafico temporale, l’ACF e la conoscenza del generatore consentono di valutare il risultato dei test entro un esperimento controllato.''',codice=c,richiamo='Un p-value limitato da una tavola deve essere comunicato con la disuguaglianza pertinente.',origine='M09:89–95')

m.sezione_nuova('Laboratorio e riferimenti')
p('La diagnosi prepara una valutazione temporale',
'''La consegna comprende controllo del calendario, copertura degli aggregati, grafico dei livelli, trasformazioni motivate e ACF delle serie derivate. Per ogni passaggio si conserva il legame con la data e si esplicita se la procedura utilizzi informazioni successive all’istante analizzato. Il confronto fra detrending, differenza ordinaria e differenza stagionale deve spiegare quale proprietà ciascuna operazione cerchi di rappresentare. Il modulo seguente utilizzerà soltanto il passato disponibile per stimare e valutare previsioni.''',destra='Esercizio conclusivo: rimescolare l’AR(1), confrontare istogramma e ACF, quindi differenziare il rumore bianco. Spiegare perché la prima operazione conserva la distribuzione marginale e la seconda introduce una correlazione negativa al primo ritardo.',richiamo='La descrizione retrospettiva e la previsione devono essere distinte attraverso la disponibilità dell’informazione.',origine='M09:102–107,110')
p('Riferimenti per processi e trasformazioni',
'''Hyndman e Athanasopoulos, Forecasting: Principles and Practice, collegano esplorazione, stazionarietà e previsione con esempi riproducibili. La documentazione R di ts, acf, filter, loess e diff definisce le convenzioni delle trasformazioni, mentre le pagine di tseries esplicitano le ipotesi dei test ADF e KPSS. I metadati allegati descrivono la provenienza storica della CO₂ e la costruzione dell’aggregato mensile. Le simulazioni rendono note alcune proprietà dei processi, permettendo verifiche analitiche del codice.''',destra='Gli script delle figure controllano decomposizione della temperatura, formula campionaria dell’ACF, ricostruzione dei livelli e commutatività delle differenze. La tabella dei test conserva le specificazioni; gli avvisi sono registrati nei log di esecuzione.',richiamo='La diagnosi deve integrare modello del processo, grafici, trasformazioni e risultati numerici.',fonti='FPP3; R; tseries',origine='M09:108–109')
m.salva()
